// TH16 v1.00a stage 6 final boss 4th non-spell (source Boss4).
// Source: st06bs.ecl.txt:416-504, firing helper Boss4_at at 506-547.

const TH16_KUNAI: int = 496;   // source type 9; copy of transcribe/th16/touhou-bullets.ecl

const TIME_LIMIT: int = 2524;      // 120 shell buffer + 2400 source timer + 4 startup
const OPENING_BUFFER: int = 120;

// Boss4_at: $C = 241, body runs 241 times, one ring per frame.
const SHOTS: int = 241;

// Source moveLimit(0.0f, 128.0f, 240.0f, 32.0f) at st06bs.ecl.txt:461.
// Position clamp is the full rect; moveRand's direction zones use centre +- width/4, height/4.
const LIMIT_X: fx = 120fx;
const LIMIT_Y_TOP: fx = 112fx;
const LIMIT_Y_BOT: fx = 144fx;
const ZONE_X: fx = 60fx;
const ZONE_Y_TOP: fx = 120fx;
const ZONE_Y_BOT: fx = 136fx;

// Source boss anchor (Boss() movePos(0.0f, 128.0f)); card entry keeps the boss there.
const BOSS_X: fx = 0fx;
const BOSS_Y: fx = 128fx;

// VELTIME (etEx type 0x200000) ramps the scalar speed linearly, keeping the angle.
xformdef VELTIME_RAMP(target: fx) {
    step_speed(target, 60);
}

// Source ANIM effect applies position -= 4 * speed on birth; with etDist 24 and
// initial speed 0.5 the net birth distance is 24 - 4 * 0.5 = 22 px along the angle.
sub configure_shooter(count: int, target: fx) {
    sh_reset(0);
    sh_sprite(0, TH16_KUNAI, 6);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, count, 1);
    sh_speed(0, 0.5fx, 0fx);
    sh_dist(0, 22fx);
    sh_xform(0, VELTIME_RAMP(target));
}

// One moveRand step: source speed(k) = s * (1 - k / frames), linear decay from the
// configured direction; the limit clamps the position each tick. Armed one tick ahead
// because the target integrates movement after the ECL phase.
sub arm_move_step(frames: int, spd: fx) {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var step: fx = 0fx;
    if k <= frames {
        step = spd * ((frames - k) as fx) / (frames as fx);
    }
    var nx: fx = $self_x + self_fx(0) * step;
    var ny: fx = $self_y + self_fx(1) * step;
    if nx < -LIMIT_X { nx = -LIMIT_X; }
    if nx > LIMIT_X { nx = LIMIT_X; }
    if ny < LIMIT_Y_TOP { ny = LIMIT_Y_TOP; }
    if ny > LIMIT_Y_BOT { ny = LIMIT_Y_BOT; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

// moveRand(frames, mode, speed): direction is sampled once from the current position.
sub move_rand(frames: int, spd: fx) {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -ZONE_X {
        a = r / 3;
    } else if $self_x > ZONE_X {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < ZONE_Y_TOP {
        if a < 0 { a = -a; }
    } else if $self_y > ZONE_Y_BOT {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Source guard pushes directions within 0.05 rad of +-pi/2 to the side they were on.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    arm_move_step(frames, spd);
}

// Source wait(n) inside the attack, with the next movement tick armed behind it.
sub attack_wait(n: int, frames: int, spd: fx) {
    for i in 0..n {
        wait(1);
        arm_move_step(frames, spd);
    }
}

// Boss4_at(angle): one fixed-direction ring per frame for 241 frames, base angle
// advancing by `turn` each shot (source %B starts at 0 and is incremented after etOn).
sub boss4_at(turn: angle, frames: int, spd: fx) {
    var b: angle = 0deg;
    for i in 0..SHOTS {
        sh_angle(0, b, 0deg);
        sh_fire(0);
        b = b + turn;
        wait(1);
        arm_move_step(frames, spd);
    }
}

async sub boss_attack() {
    set_invuln(65535);
    set_hitbox(25fx);     // source setHitbox(50.0f, 50.0f)
    set_hurtbox(28fx);    // source setHurtbox(56.0f, 56.0f)

    var rank: int = global(GVAR_RANK);
    var count: int = 4;
    var target: fx = 3fx;
    var turn: angle = 8deg;
    if rank == RANK_EASY {
        count = 1;
        target = 3fx;
        turn = 8deg;
    } else if rank == RANK_HARD {
        count = 4;
        target = 3.4fx;
        turn = 5deg;
    } else if rank == RANK_LUNATIC {
        count = 5;
        target = 4.5fx;
        turn = 5deg;
    }
    configure_shooter(count, target);

    wait(60);
    wait(60);
    wait(60);

    loop {
        move_rand(240, 0.5fx);
        boss4_at(-turn, 240, 0.5fx);
        move_rand(60, 1.9fx);
        attack_wait(60, 60, 1.9fx);
        move_rand(240, 0.5fx);
        boss4_at(turn, 240, 0.5fx);
        move_rand(60, 1.9fx);
        attack_wait(60, 60, 1.9fx);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(BOSS_X, BOSS_Y, 18000, 0, 0, 0, boss_attack);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
